const fs = await import('node:fs');
const path = await import('node:path');
const inputPath = process.env.INPUT_PATH;
const outputPath = process.env.OUTPUT_PATH;
if (!inputPath || !outputPath) throw new Error('INPUT_PATH and OUTPUT_PATH are required');
const raw = fs.readFileSync(inputPath, 'utf8');
let data;
try { data = JSON.parse(raw); } catch (e) { throw new Error('Invalid JSON: ' + e.message); }
globalThis.jsonData = data;
globalThis.outputPath = outputPath;
fs.mkdirSync(path.dirname(outputPath), { recursive: true });

const fs = await import('node:fs');
const { encode } = await import('algorand-msgpack');
const encoded = encode(globalThis.jsonData);
const buffer = Buffer.from(encoded.buffer, encoded.byteOffset, encoded.byteLength);
fs.writeFileSync(globalThis.outputPath, buffer);
globalThis.result = { output_path: globalThis.outputPath, bytes: buffer.length };

const result = globalThis.result;
if (!result) throw new Error('Missing execution result');
console.log(JSON.stringify({ output_path: result.output_path }));
